import json, sys, heapq
sys.path.insert(0,"/work/submission")

def trace(doc, label):
    n=doc["n"]; capacity=doc["capacity"]; edges=doc["edges"]; rounds=doc["rounds"]
    out=[[] for _ in range(n)]
    for i,e in enumerate(edges): out[e["u"]].append(i)
    R=len(rounds); dl=[r["launch_us"]+r["timeout_us"] for r in rounds]
    log=[]
    heap=[]; seq=[0]
    def push(t,prio,rid,key,kind,payload=None):
        seq[0]+=1; heapq.heappush(heap,(t,prio,rid,key,seq[0],kind,payload))
    for rid,r in enumerate(rounds):
        push(r["launch_us"],2,rid,-1,"ping"); push(dl[rid]+1,1,rid,-1,"release")
    ent={}; rnodes=[set() for _ in range(R)]; ncnt=[0]*n; tot=0
    def tx(rid,eid,proof,comp,now):
        log.append(("txack",now,rid,eid,sorted(proof),comp))
        if eid not in rounds[rid]["drop_ack"]:
            push(now+edges[eid]["ack_us"],3,rid,eid,"ack",(proof,comp))
    def fin(rid,node,e,comp,now):
        log.append(("final",now,rid,node,comp,sorted(e["proof"])))
        e["fin"]=True; e["comp"]=comp; e["frozen"]=frozenset(e["proof"])
        for pe in e["parents"]: tx(rid,pe,e["frozen"],comp,now)
        if node==0:
            log.append(("srcfinal",now,rid,comp,sorted(e["frozen"])))
            if not rounds[rid]["drop_host_ack"]:
                push(now+rounds[rid]["host_delay_us"],5,rid,-1,"hostack")
    while heap:
        t,prio,rid,key,s,kind,payload=heapq.heappop(heap)
        if kind=="release":
            for nd in rnodes[rid]: del ent[(rid,nd)]; ncnt[nd]-=1; tot-=1
            rnodes[rid].clear(); log.append(("release",t,rid)); continue
        if kind=="ping":
            if key==-1: nd=0; eid=None
            else: eid=key; nd=edges[eid]["v"]
            if t>dl[rid]: log.append(("late",t,rid,eid)); continue
            e=ent.get((rid,nd))
            if e is not None:
                log.append(("dedup",t,rid,eid,nd,e["fin"]))
                if eid is not None:
                    e["parents"].add(eid)
                    if e["fin"]: tx(rid,eid,e["frozen"],e["comp"],t)
                continue
            if ncnt[nd]>=capacity[nd]: log.append(("capdrop",t,rid,eid,nd)); continue
            log.append(("alloc",t,rid,nd,eid))
            e=dict(proof=set(),credited=set(),cc={},parents=set(),fin=False,comp=None,frozen=frozenset())
            ent[(rid,nd)]=e; rnodes[rid].add(nd); ncnt[nd]+=1; tot+=1
            if eid is not None: e["parents"].add(eid)
            push(dl[rid],4,rid,nd,"timeout")
            for oe in out[nd]:
                log.append(("txping",t,rid,oe))
                if oe not in rounds[rid]["drop_ping"]:
                    push(t+edges[oe]["ping_us"],2,rid,oe,"ping")
            if not out[nd]: fin(rid,nd,e,True,t)
            continue
        if kind=="ack":
            eid=key; nd=edges[eid]["u"]; e=ent.get((rid,nd))
            if e is None or e["fin"] or eid in e["credited"]:
                log.append(("ignore",t,rid,eid,"none" if e is None else ("fin" if e["fin"] else "credited")))
                continue
            proof,comp=payload
            e["credited"].add(eid); e["cc"][eid]=comp; e["proof"]|=proof; e["proof"].add(eid)
            log.append(("credit",t,rid,eid,nd,sorted(e["proof"])))
            if len(e["credited"])==len(out[nd]): fin(rid,nd,e,all(e["cc"].values()),t)
            continue
        if kind=="timeout":
            nd=key; e=ent.get((rid,nd))
            if e is None or e["fin"]: log.append(("timeout-noop",t,rid,nd)); continue
            log.append(("timeout",t,rid,nd))
            fin(rid,nd,e,False,t); continue
        if kind=="hostack":
            log.append(("hostdel",t,rid)); continue
    return log

if __name__=="__main__":
    doc=json.load(open(sys.argv[1]))
    for line in trace(doc,"a"): print(line)
